      c: ['객체가 포인터로 흩어져 있고 순서 없이 접근', 'CPU 캐시에 없어서 매번 RAM에서 읽음(100배 안팎 느림)', '같은 일을 해도 틱 비용이 몇 배, 심하면 슬로우모션'],
      sym: ['slowmo'], fx: ['stall'], who: ['server'], when: ['always', 'event'],
      own: ['srv'],
      act: { game: '자주 함께 쓰는 데이터를 연속으로 배치(데이터 지향 설계).' },
