  add('db', [
    { id: 'db-no-index', t: '인덱스 없는 쿼리', en: 'Missing index / full table scan',
      s: '인덱스 없이 조건에 맞는 행을 찾으려면 테이블 전체를 읽어야 합니다(풀 스캔).',
      c: ['새 기능 배포로 인덱스가 없는 조건 검색 추가', '수백만 행을 모두 스캔해 쿼리 하나에 수백 ms~수 초', '우편함·거래 기록 로딩 지연, 커넥션이 묶여 다른 요청까지 대기'],
      sym: ['delay', 'noconnect'], fx: ['lat', 'stall'], who: ['feature', 'server'], when: ['action'],
      num: '인덱스가 있으면 수 ms, 없으면 데이터 크기에 비례해 느려져 큰 테이블에서는 수백~수만 배.',
      own: ['srv', 'dba'],
      act: { game: '새 쿼리는 배포 전 실행 계획 검토, 인덱스 추가, 고치는 쿼리(UPDATE·DELETE)도 인덱스를 타는지 확인.', infra: '느린 쿼리 로그 감시, 풀 스캔 쿼리를 찾아 게임팀에 공유, 운영 중 인덱스 추가는 잠금이 짧은 온라인 방식으로 적용.' },
      more: '읽기만 느려지는 것이 아닙니다. 인덱스 없이 고치는 쿼리(UPDATE·DELETE)는 DB에 따라 스캔한 행까지 잠가, 상관없는 플레이어의 저장까지 막을 수 있습니다.',
      sim: 'dbpool',
      sig: { k: 'step', g: 'DB 쿼리 지연, 읽은 행 수' },
      chk: {
        look: 'MySQL은 slow query log(log_queries_not_using_indexes를 켜면 인덱스를 안 쓴 쿼리도 기록)의 Rows_examined·Rows_sent, performance_schema events_statements_summary_by_digest의 SUM_NO_INDEX_USED·SUM_ROWS_EXAMINED를 보고 EXPLAIN을 돌림. PostgreSQL은 pg_stat_user_tables의 seq_scan·seq_tup_read를 보고 EXPLAIN을 돌림',
        yes: '배포 뒤 새로 나타난 쿼리가 돌려준 행(Rows_sent)보다 수천 배 많은 행을 읽고(Rows_examined), EXPLAIN에 테이블 전체 스캔(MySQL type ALL, PostgreSQL Seq Scan)이 나옴. 큰 테이블의 seq_tup_read가 배포 시각부터 가파르게 늘어남',
        no: '인덱스를 타는데도 느리면 잠금 대기(db-hot-row, db-ddl-lock)나 실행 계획 변경(db-plan-flip). 작은 테이블의 전체 스캔은 정상일 수 있음',
        by: 'ops',
      },
      ref: [
        { t: 'How MySQL Uses Indexes', u: 'https://dev.mysql.com/doc/refman/8.4/en/mysql-indexes.html', p: 'MySQL', n: '인덱스가 없으면 첫 행부터 테이블 전체를 읽고, 테이블이 클수록 비용이 커짐' },
        { t: 'Locks Set by Different SQL Statements in InnoDB', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-locks-set.html', p: 'MySQL', n: '맞는 인덱스가 없어 테이블 전체를 스캔하면 모든 행이 잠겨 다른 사용자의 추가까지 막힘' },
        { t: 'The Slow Query Log', u: 'https://dev.mysql.com/doc/refman/8.4/en/slow-query-log.html', p: 'MySQL', n: 'long_query_time(기본 10초)을 넘긴 쿼리 기록, 인덱스를 안 쓰는 쿼리도 따로 기록 가능' },
        { t: 'CREATE INDEX (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/sql-createindex.html', p: 'PostgreSQL', n: 'CONCURRENTLY로 만들면 쓰기를 막지 않고 인덱스 생성, 일반 생성은 끝날 때까지 쓰기를 막음' },
        { t: 'Statement Summary Tables', u: 'https://dev.mysql.com/doc/refman/8.4/en/performance-schema-statement-summary-tables.html', p: 'MySQL', n: 'events_statements_summary_by_digest: 같은 모양 쿼리별 SUM_NO_INDEX_USED(인덱스 없이 실행한 횟수)·SUM_ROWS_EXAMINED' },
        { t: 'EXPLAIN Output Format', u: 'https://dev.mysql.com/doc/refman/8.4/en/explain-output.html', p: 'MySQL', n: 'type이 ALL이면 테이블 전체 스캔, 보통 인덱스를 추가해 피함' },
        { t: 'The Cumulative Statistics System (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/monitoring-stats.html', p: 'PostgreSQL', n: 'pg_stat_user_tables의 seq_scan(순차 스캔 횟수)·seq_tup_read(순차 스캔으로 읽은 행 수)' },
        { t: 'Using EXPLAIN (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/using-explain.html', p: 'PostgreSQL', n: 'Seq Scan: 테이블의 모든 행을 차례로 읽는 실행 계획' },
      ] },
    { id: 'db-hot-row', t: '핫 로우 잠금 경합', en: 'Hot row lock contention',
      s: '모두가 같은 행(길드 창고, 경매장 인기 아이템, 서버 전체 카운터)을 고치려 하면 한 명씩만 잠금을 얻습니다.',
      c: ['이벤트·인기 아이템으로 같은 행에 수정이 몰림', '잠금을 얻을 때까지 요청이 대기', '거래 실패, “잠시 후 다시 시도”, 타임아웃'],
      sym: ['dropped', 'delay'], fx: ['stall', 'lat'], who: ['feature'], when: ['event'],
      num: '한 요청이 잠금을 10ms 잡고 있으면 그 행은 1초에 최대 100번만 고칠 수 있습니다. 트랜잭션 안에 다른 서버 왕복이 끼면 그만큼 더 줄어듭니다.',
      own: ['srv', 'dba'],
      act: { game: '행을 나누기(샤딩된 카운터), 트랜잭션 짧게, 메모리에서 모아 한 번에 반영.', infra: '행 잠금 대기 시간·건수를 모니터링해 경합이 몰리는 행을 찾아 공유.' },
      sim: 'dbpool',
      sig: { k: 'load', g: '행 잠금 대기 수·시간' },
      chk: {
        look: 'MySQL은 Innodb_row_lock_waits·Innodb_row_lock_time 증가량과 Innodb_row_lock_current_waits를 보고, sys.innodb_lock_waits로 누가 누구를 기다리는지 찾음. PostgreSQL은 pg_stat_activity에서 wait_event_type이 Lock인 세션, pg_locks에서 granted가 false인 요청을 보고, log_lock_waits(기본 꺼짐)를 켜면 오래 기다린 잠금이 로그에 남음',
        yes: '이벤트·인원을 따라 잠금 대기가 가파르게 늘고, 기다리는 요청 대부분이 같은 테이블의 같은 행(같은 키)을 가리킴',
        no: '대기가 여러 테이블·행에 고르게 흩어지면 디스크·CPU 포화 쪽. 한 세션이 잠금을 오래 잡고 놓지 않으면 오래 열린 트랜잭션(db-long-tx)',
        by: 'ops',
      },
      ref: [
        { t: 'InnoDB Locking', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-locking.html', p: 'MySQL', n: '한 트랜잭션이 행(인덱스 레코드)에 잠금을 걸면 다른 트랜잭션은 그 행을 고치지 못하고 기다림' },
        { t: 'How to Minimize and Handle Deadlocks', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-deadlocks-handling.html', p: 'MySQL', n: '트랜잭션을 작고 짧게 유지하고 관련 변경 직후 바로 커밋해 충돌을 줄이라는 권고' },
        { t: 'Server Status Variables', u: 'https://dev.mysql.com/doc/refman/8.4/en/server-status-variables.html', p: 'MySQL', n: 'Innodb_row_lock_waits·Innodb_row_lock_time으로 행 잠금 대기 횟수와 시간, Innodb_row_lock_current_waits로 지금 기다리는 수를 확인' },
        { t: 'The innodb_lock_waits and x$innodb_lock_waits Views', u: 'https://dev.mysql.com/doc/refman/8.4/en/sys-innodb-lock-waits.html', p: 'MySQL', n: '기다리는 쿼리(waiting_query)와 막고 있는 세션(blocking_pid), 대기 시간(wait_age)' },
        { t: 'The Cumulative Statistics System (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/monitoring-stats.html', p: 'PostgreSQL', n: 'pg_stat_activity의 wait_event_type: Lock이면 무거운 잠금을 기다리는 중' },
        { t: 'pg_locks (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/view-pg-locks.html', p: 'PostgreSQL', n: 'granted가 false면 그 프로세스가 잠금을 얻으려고 기다리는 중' },
        { t: 'Error Reporting and Logging (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/runtime-config-logging.html', p: 'PostgreSQL', n: 'log_lock_waits: deadlock_timeout보다 오래 잠금을 기다리면 로그를 남김, 기본 꺼짐' },
      ] },
    { id: 'db-deadlock', t: 'DB 데드락', en: 'Database deadlock',
      s: '두 트랜잭션(한 묶음으로 처리되는 DB 작업)이 서로 상대가 잠근 행을 기다리면 DB가 한쪽을 강제로 취소합니다.',
      c: ['거래 A는 아이템→재화, B는 재화→아이템 순서로 잠금', 'DB가 데드락을 감지해 한쪽을 롤백', '거래·제작이 가끔 실패, 아이템이 되돌아감'],
      sym: ['dropped', 'delay'], fx: ['loss', 'stall'], who: ['feature'], when: ['event', 'action'],
      num: '감지까지 MySQL(InnoDB)은 거의 즉시, PostgreSQL은 기본 1초, SQL Server는 최대 5초쯤 걸립니다. 그동안 두 요청 모두 멈춰 있습니다. 동시 요청이 아주 많아 MySQL의 감지를 꺼 둔 서버라면 잠금 대기 한도(기본 50초)까지 기다립니다.',
      own: ['srv', 'dba'],
      act: { game: '잠금 순서 통일, 트랜잭션 짧게, 실패 시 자동 재시도.', infra: '데드락 감지를 켜 두고 데드락 기록을 수집해 공유, 감지를 끈 MySQL 서버는 잠금 대기 한도(기본 50초) 줄이기.' },
      sig: { k: 'random', g: '데드락 수, 거래 실패 수' },
      chk: {
        look: 'MySQL은 SHOW ENGINE INNODB STATUS의 LATEST DETECTED DEADLOCK(가장 최근 1건), innodb_print_all_deadlocks를 켜면 에러 로그에 남는 모든 데드락, INFORMATION_SCHEMA.INNODB_METRICS의 lock_deadlocks를 봄. PostgreSQL은 pg_stat_database의 deadlocks, SQL Server는 기본으로 켜진 system_health 세션의 xml_deadlock_report를 봄. 게임 서버 쪽 오류 코드는 MySQL 1213, PostgreSQL 40P01, SQL Server 1205',
        yes: '거래·제작 실패 시각에 데드락 수가 늘고, 기록된 두 트랜잭션이 같은 테이블들을 서로 반대 순서로 잠그고 있음',
        no: '데드락 수는 그대로인데 실패하면 잠금 대기 한도 초과(MySQL 오류 1205)나 핫 로우(db-hot-row)',
        by: 'ops',
      },
      ref: [
        { t: 'InnoDB Startup Options and System Variables', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-parameters.html', p: 'MySQL', n: '감지가 켜져 있으면(기본) InnoDB는 데드락을 즉시 감지해 롤백, innodb_lock_wait_timeout 기본 50초' },
        { t: 'Deadlock Detection', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-deadlock-detection.html', p: 'MySQL', n: '동시성이 아주 높으면 감지 자체가 느려질 수 있어 끄고 잠금 대기 한도에 맡기기도 함' },
        { t: 'Lock Management (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/runtime-config-locks.html', p: 'PostgreSQL', n: 'deadlock_timeout 기본 1초: 이만큼 잠금을 기다린 뒤에야 데드락 검사' },
        { t: 'Deadlocks guide', u: 'https://learn.microsoft.com/en-us/sql/relational-databases/sql-server-deadlocks-guide', p: 'Microsoft SQL Server', n: '데드락 검사 기본 간격 5초, 데드락이 자주 나면 100ms까지 줄어듦, 기본으로 켜진 system_health 세션이 xml_deadlock_report를 수집, 희생된 쪽은 오류 1205' },
        { t: 'How to Minimize and Handle Deadlocks', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-deadlocks-handling.html', p: 'MySQL', n: '여러 행·테이블은 늘 같은 순서로 고치기, 실패하면 다시 시도, innodb_print_all_deadlocks로 모든 데드락 기록' },
        { t: 'InnoDB Standard Monitor and Lock Monitor Output', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-standard-monitor.html', p: 'MySQL', n: 'LATEST DETECTED DEADLOCK: 가장 최근 데드락의 두 트랜잭션, 잡은·기다린 잠금, 롤백한 쪽' },
        { t: 'InnoDB INFORMATION_SCHEMA Metrics Table', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-information-schema-metrics-table.html', p: 'MySQL', n: 'INNODB_METRICS의 lock_deadlocks 카운터(기본 활성)' },
        { t: 'Server Error Message Reference', u: 'https://dev.mysql.com/doc/mysql-errors/8.4/en/server-error-reference.html', p: 'MySQL', n: '1213 ER_LOCK_DEADLOCK(데드락), 1205 ER_LOCK_WAIT_TIMEOUT(잠금 대기 한도 초과)' },
        { t: 'The Cumulative Statistics System (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/monitoring-stats.html', p: 'PostgreSQL', n: 'pg_stat_database의 deadlocks: 이 DB에서 감지한 데드락 수' },
        { t: 'PostgreSQL Error Codes (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/errcodes-appendix.html', p: 'PostgreSQL', n: '40P01 deadlock_detected' },
      ] },
    { id: 'db-pool', t: '커넥션 풀 고갈', en: 'Connection pool exhaustion',
      s: 'DB와 맺어 둔 연결 수가 정해져 있어서, 느린 쿼리가 연결을 점유하면 나머지는 대기합니다.',
      c: ['느린 쿼리나 요청 폭주로 모든 연결이 사용 중', '새 요청은 연결이 날 때까지 대기', '로그인 무한 로딩, 저장 지연, 타임아웃'],
      sym: ['noconnect', 'delay'], fx: ['stall', 'lat'], who: ['server', 'feature'], when: ['login', 'event'],
      num: '필요한 연결 수는 “초당 요청 × 한 건이 연결을 점유하는 시간”으로 어림합니다. 1초에 2,000건, 건당 5ms면 평균 10개가 늘 바쁩니다. 몰릴 때를 생각해 보통 그 두세 배를 둡니다. 쿼리가 150ms로 느려지면 같은 요청에 300개가 필요해집니다.',
      own: ['srv', 'dba'],
      act: { game: '느린 쿼리 제거, 풀 크기와 대기 타임아웃 조정(풀을 무작정 키우지 않기), 기능별 풀 분리.', infra: 'DB의 최대 연결 수와 CPU·IOPS 여유 확인, 증설·오토스케일링 전에 서버 수 × 풀 크기가 최대 연결 수 안인지 확인, 커넥션 대기·락 대기 지표를 모니터링에 추가.' },
      more: '풀을 무작정 키우면 DB CPU와 잠금 경쟁만 늘어 모두가 같이 느려집니다. 또 서버 수 × 풀 크기가 DB의 최대 연결 수를 넘으면, 증설한 서버나 재시작한 서버가 연결조차 못 맺습니다. 오토스케일링이나 점검 직후에 흔합니다.',
      sim: 'dbpool',
      sig: { k: 'ceiling', g: '사용 중 DB 연결 수, 커넥션 대기 시간' },
      chk: {
        look: 'DB 쪽에서 게임 서버별 연결 상태를 셈. MySQL은 SHOW PROCESSLIST의 Host·Command(쉬는 연결은 Sleep)·Time과 Threads_connected·Threads_running, 거부된 연결 수 Connection_errors_max_connections를 봄. PostgreSQL은 pg_stat_activity를 client_addr·state로 묶어 셈. 게임 서버의 커넥션 풀 라이브러리가 대기 수·대기 시간을 내보내면 함께 봄',
        yes: '한 게임 서버의 연결이 풀 크기만큼 모두 쿼리 실행 중이고 쉬는 연결이 0인 동안 로그인·저장이 대기함. 또는 DB 전체 연결 수가 max_connections에 닿아 새 연결이 거부됨',
        no: '쉬는 연결이 넉넉한데도 느리면 쿼리 자체의 지연(db-no-index, db-hot-row)이나 DB 자원 포화 쪽',
        by: 'ops',
      },
      ref: [
        { t: 'Number Of Database Connections', u: 'https://wiki.postgresql.org/wiki/Number_Of_Database_Connections', p: 'PostgreSQL', n: 'DB 자원을 다 쓴 뒤에는 연결을 늘려도 처리량이 오히려 떨어짐, 활성 연결을 자원에 맞추고 나머지는 대기열에 두는 편이 지연·처리량 모두 좋음' },
        { t: 'Too many connections', u: 'https://dev.mysql.com/doc/refman/8.4/en/too-many-connections.html', p: 'MySQL', n: 'max_connections를 모두 쓰면 새 연결이 Too many connections 오류로 거부됨' },
        { t: 'Connections and Authentication (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/runtime-config-connection.html', p: 'PostgreSQL', n: 'max_connections: 동시 연결 수 상한, 기본은 보통 100' },
        { t: 'SHOW PROCESSLIST Statement', u: 'https://dev.mysql.com/doc/refman/8.4/en/show-processlist.html', p: 'MySQL', n: 'Host(클라이언트 주소), Command(쉬는 세션은 Sleep), Time, State' },
        { t: 'Server Status Variables', u: 'https://dev.mysql.com/doc/refman/8.4/en/server-status-variables.html', p: 'MySQL', n: 'Threads_connected·Threads_running, Connection_errors_max_connections(max_connections에 닿아 거부된 연결 수)' },
        { t: 'The Cumulative Statistics System (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/monitoring-stats.html', p: 'PostgreSQL', n: 'pg_stat_activity: 연결마다 client_addr와 state(active, idle, idle in transaction 등)' },
      ] },
    { id: 'db-replica-lag', t: '복제 지연', en: 'Replication lag',
      s: '쓰기는 주 DB에, 읽기는 복제본에서 하는데 복제본이 늦게 따라오면 방금 쓴 내용이 안 보입니다.',
      c: ['주 DB에 쓰기가 몰려 복제본이 수 초 뒤처짐', '방금 저장한 내용을 복제본에서 읽으면 아직 없음', '방금 산 아이템이 안 보임, 거래소 가격이 옛날 값, 중복 지급 버그'],
      sym: ['dropped'], fx: ['lat'], who: ['feature'], when: ['event', 'peak'],
      own: ['dba', 'srv'],
      act: { game: '방금 쓴 데이터는 주 DB에서 읽기, 지급 여부 확인과 지급은 주 DB에서 한 트랜잭션으로(유니크 키나 조건부 UPDATE로 중복 차단).', infra: '복제 지연 경보, 복제본 사양을 주 DB 이상으로 두고 병렬 복제 적용, 대량 삭제는 잘게 나눠 실행, 복제본에서 오래 도는 집계 쿼리 관리.' },
      more: '쓰기가 많지 않아도 뒤처질 수 있습니다. 주 DB에서 10분 걸린 대량 삭제 하나는 복제본에서도 다시 실행되는 동안 그만큼 뒤처지게 만들고, 복제본에서 오래 도는 집계 쿼리도 따라가기를 늦춥니다.',
      sim: 'arch',
      sig: { k: 'load', g: '복제 지연(초)' },
      chk: {
        look: 'MySQL은 복제본에서 SHOW REPLICA STATUS의 Seconds_Behind_Source(8.0.22 이전 버전은 SHOW SLAVE STATUS)를 봄. PostgreSQL은 주 서버 pg_stat_replication의 write_lag·flush_lag·replay_lag, RDS는 ReplicaLag를 봄',
        yes: '“안 보인다”는 제보 시각에 지연이 수 초 이상이고, 지연이 풀린 뒤 다시 보면 정상. 쓰기 폭주나 대량 삭제, 복제본의 긴 집계 쿼리 시각에 지연이 커짐',
        no: '지연이 0 근처인데도 안 보이면 게임 서버의 캐시나 동기화 쪽',
        by: 'ops',
      },
      ref: [
        { t: 'SHOW REPLICA STATUS Statement', u: 'https://dev.mysql.com/doc/refman/8.4/en/show-replica-status.html', p: 'MySQL', n: 'Seconds_Behind_Source: 복제본이 지금 적용 중인 이벤트가 주 DB에서 기록된 시각과의 차이(복제 지연)' },
        { t: 'Replica Server Options and Variables', u: 'https://dev.mysql.com/doc/refman/8.4/en/replication-options-replica.html', p: 'MySQL', n: 'replica_parallel_workers로 여러 스레드가 트랜잭션을 병렬 적용(기본 4, 0이면 한 스레드가 순서대로)' },
        { t: 'Log-Shipping Standby Servers (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/warm-standby.html', p: 'PostgreSQL', n: '스트리밍 복제는 기본 비동기라 커밋과 복제본 반영 사이에 지연이 있음(복제본이 따라갈 수 있으면 보통 1초 미만)' },
        { t: 'MySQL 8.0 Reference Manual: SHOW REPLICA STATUS Statement', u: 'https://dev.mysql.com/doc/refman/8.0/en/show-replica-status.html', p: 'MySQL', n: '8.0.22부터 SHOW SLAVE STATUS 대신 SHOW REPLICA STATUS, 그 이전 버전은 SHOW SLAVE STATUS' },
        { t: 'The Cumulative Statistics System (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/monitoring-stats.html', p: 'PostgreSQL', n: 'pg_stat_replication의 write_lag·flush_lag·replay_lag: 주 서버가 WAL을 기록한 뒤 복제본이 쓰고·디스크에 내리고·적용했다고 알릴 때까지 걸린 시간' },
        { t: 'Amazon CloudWatch metrics for Amazon RDS', u: 'https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-metrics.html', p: 'AWS', n: 'ReplicaLag: 읽기 복제본이 원본보다 뒤처진 시간(초)' },
      ] },
    { id: 'db-checkpoint', t: '체크포인트·로그 플러시', en: 'Checkpoint / log flush stalls',
      s: 'DB가 메모리의 변경분을 주기적으로 디스크에 몰아서 쓰는 순간 쿼리가 느려집니다.',
      c: ['변경분이 쌓여 주기적으로 디스크에 기록', '그 순간 디스크가 바빠져 쿼리 지연', '주기적으로 저장·로딩이 느려짐'],
      sym: ['delay', 'stutter'], fx: ['lat'], who: ['server', 'feature'], when: ['periodic'],
      own: ['dba'],
      act: { infra: '체크포인트를 잘게 나눠 고르게, 트랜잭션 로그(redo 로그, WAL)를 넉넉하게, 빠른 디스크.' },
      more: '변경 기록을 담는 트랜잭션 로그(MySQL의 redo 로그, PostgreSQL의 WAL)를 너무 작게 잡으면, 로그가 찰 때마다 DB가 급하게 체크포인트를 몰아 하느라 쓰기 처리량이 잠깐씩 크게 떨어집니다.',
      sig: { k: 'periodic', g: 'DB 쿼리 지연, 디스크 쓰기량' },
      chk: {
        look: 'PostgreSQL은 log_checkpoints(최근 버전은 기본으로 켜짐) 로그의 체크포인트 시각과 쓴 버퍼 수, 체크포인트 횟수(17 이후 pg_stat_checkpointer의 num_timed·num_requested, 16 이하 pg_stat_bgwriter의 checkpoints_timed·checkpoints_req), checkpoint_warning 경고를 봄. MySQL은 SHOW ENGINE INNODB STATUS의 LOG 섹션에서 Log sequence number와 Last checkpoint at의 차이를 봄. 서버의 디스크 쓰기량·쓰기 지연을 함께 겹침',
        yes: '쿼리 지연이 튄 시각이 체크포인트 시각과 겹치고 그때 디스크 쓰기량과 쓰기 지연이 솟음. PostgreSQL에서 요청 체크포인트(num_requested)가 시간 체크포인트(num_timed)보다 훨씬 많으면 WAL이 max_wal_size에 자주 닿아 체크포인트가 앞당겨지는 것으로 봄',
        no: '체크포인트 시각과 무관한 주기로 튀면 백업·배치(dk-backup, db-batch)',
        by: 'ops',
      },
      ref: [
        { t: 'WAL Configuration (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/wal-configuration.html', p: 'PostgreSQL', n: '체크포인트는 기본 5분 또는 WAL 1GB(max_wal_size)마다, 더티 페이지를 모두 써서 비쌈. checkpoint_completion_target으로 쓰기를 나눠 I/O 폭주를 피함. 체크포인트 간격이 checkpoint_warning보다 짧으면 max_wal_size를 늘리라는 경고를 로그에 남김' },
        { t: 'Configuring Buffer Pool Flushing', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-buffer-pool-flushing.html', p: 'MySQL', n: 'redo 로그가 차면 급한(sharp) 체크포인트로 처리량이 잠깐 떨어짐, 적응형 플러시로 고르게 나눠 씀' },
        { t: 'Error Reporting and Logging (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/runtime-config-logging.html', p: 'PostgreSQL', n: 'log_checkpoints: 체크포인트마다 쓴 버퍼 수와 걸린 시간을 로그에 남김, 기본 켜짐' },
        { t: 'The Cumulative Statistics System (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/monitoring-stats.html', p: 'PostgreSQL', n: 'pg_stat_checkpointer의 num_timed(시간이 되어 한 체크포인트)·num_requested(요청된 체크포인트)' },
        { t: 'PostgreSQL 17 Release Notes', u: 'https://www.postgresql.org/docs/release/17.0/', p: 'PostgreSQL', n: 'pg_stat_checkpointer 신설, 체크포인트 관련 열을 pg_stat_bgwriter에서 옮김' },
        { t: 'The Cumulative Statistics System (PostgreSQL 16 Documentation)', u: 'https://www.postgresql.org/docs/16/monitoring-stats.html', p: 'PostgreSQL', n: '16까지는 pg_stat_bgwriter의 checkpoints_timed·checkpoints_req' },
        { t: 'InnoDB Standard Monitor and Lock Monitor Output', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-standard-monitor.html', p: 'MySQL', n: 'LOG 섹션: 현재 로그 시퀀스 번호와 마지막 체크포인트 위치' },
      ] },
    { id: 'db-cold-cache', t: '콜드 캐시 (재시작 직후)', en: 'Cold buffer pool after restart',
      s: 'DB를 재시작하면 메모리 캐시가 비어 있어서, 한동안 모든 조회가 디스크에서 읽힙니다.',
      c: ['점검으로 DB 재시작', '자주 쓰던 데이터가 메모리에 없어 디스크에서 읽음', '점검 직후 한동안 로그인·로딩이 느림'],
      sym: ['noconnect', 'delay'], fx: ['lat'], who: ['server'], when: ['login'],
      own: ['dba', 'srv'],
      act: { game: '점진적 오픈(접속 대기열로 로그인 인원을 단계적으로 늘리기).', infra: '재시작 후 캐시 예열(워밍, 버퍼 풀 저장·복원 설정 확인), 스냅샷으로 되살린 DB는 디스크도 미리 읽기.' },
      more: 'MySQL은 꺼질 때 버퍼 풀의 페이지 목록을 저장했다가 켜질 때 백그라운드에서 다시 읽어 오지만, 다 채우기까지는 시간이 걸립니다. 클라우드에서 DB를 스냅샷(디스크 사본)으로 되살렸다면 디스크 자체도 처음 읽는 블록마다 느려서 더 오래 갑니다.',
      sig: { k: 'surge', g: '디스크 읽기, 버퍼 캐시 적중률' },
      chk: {
        look: 'MySQL은 Innodb_buffer_pool_reads(버퍼 풀에 없어 디스크에서 읽은 횟수)와 Innodb_buffer_pool_read_requests의 비율, 예열 진행 상황 Innodb_buffer_pool_load_status를 봄. PostgreSQL은 pg_stat_database의 blks_read·blks_hit을 봄. DB 서버의 디스크 읽기 수도 함께 봄',
        yes: '재시작 직후 디스크 읽기가 솟고 적중률이 낮았다가 시간이 지나며 회복되고, 그 구간에 로그인·로딩이 느림',
        no: '적중률이 평소와 같은데 점검 직후 느리면 로그인 폭주·N+1(db-login-storm)이나 커넥션 풀(db-pool)',
        by: 'ops',
      },
      ref: [
        { t: 'Saving and Restoring the Buffer Pool State', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-preload-buffer-pool.html', p: 'MySQL', n: '재시작 뒤 예열 시간을 줄이려고 꺼질 때 최근 쓴 페이지 목록(기본 25%)을 저장하고 켜질 때 다시 읽음, 둘 다 기본으로 켜져 있음' },
        { t: 'pg_prewarm — preload relation data into buffer caches', u: 'https://www.postgresql.org/docs/current/pgprewarm.html', p: 'PostgreSQL', n: '공유 버퍼 내용을 주기적으로 기록해 두었다가 재시작 뒤 다시 올림(autoprewarm)' },
        { t: 'Initialize Amazon EBS volumes', u: 'https://docs.aws.amazon.com/ebs/latest/userguide/ebs-initialize.html', p: 'AWS', n: '스냅샷에서 만든 볼륨은 모든 블록을 받아 올 때까지 지연이 늘고 성능이 떨어짐' },
        { t: 'Server Status Variables', u: 'https://dev.mysql.com/doc/refman/8.4/en/server-status-variables.html', p: 'MySQL', n: 'Innodb_buffer_pool_reads(버퍼 풀에 없어 디스크에서 직접 읽은 논리 읽기 수), Innodb_buffer_pool_read_requests, Innodb_buffer_pool_load_status(예열 진행 상황)' },
        { t: 'The Cumulative Statistics System (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/monitoring-stats.html', p: 'PostgreSQL', n: 'pg_stat_database의 blks_read(디스크에서 읽은 블록 수)·blks_hit(버퍼 캐시에서 찾은 블록 수)' },
      ] },
    { id: 'db-login-storm', t: '로그인 폭주와 N+1 쿼리', en: 'Login storm, N+1 queries',
      s: '캐릭터 하나를 불러올 때 수십 번 따로 조회하면, 수만 명 동시 로그인이 쿼리 수백만 개가 됩니다.',
      c: ['캐릭터 로딩 때 아이템·스킬·퀘스트를 따로따로 조회', '점검 직후 동시 로그인으로 쿼리 폭증', '로그인 무한 로딩, 게임 중인 사람의 저장까지 밀림'],
      sym: ['noconnect', 'delay'], fx: ['stall', 'lat'], who: ['server'], when: ['login'],
      own: ['srv', 'dba'],
      act: { game: '한 번에 묶어서 조회, 접속 대기열, 캐시, ORM 지연 로딩이 만드는 조회 수 점검.', infra: '호출 횟수가 많은 쿼리 순위를 뽑아 공유, 점검 직후 로그인 시간대의 쿼리 수·커넥션 수 모니터링.' },
      more: 'ORM(DB 조회를 대신 만들어 주는 라이브러리)의 지연 로딩이 개발자도 모르는 사이 이런 조회를 만듭니다. 개발 서버에서는 캐릭터 몇 개라 티가 안 나고, 라이브의 동시 로그인에서 처음 드러납니다.',
      sim: 'dbpool',
      sig: { k: 'surge', g: 'DB 초당 쿼리 수, 로그인 수' },
      chk: {
        look: '점검 직후 로그인 수와 DB의 초당 쿼리 수(MySQL은 Questions 증가량)를 겹쳐 보고 로그인 한 건당 쿼리 수를 계산함. 호출 횟수 상위 쿼리는 MySQL events_statements_summary_by_digest의 COUNT_STAR, PostgreSQL pg_stat_statements의 calls로 뽑음',
        yes: '로그인 한 건당 쿼리가 수십 개이고, 상위 쿼리가 캐릭터 ID 하나로 조회하는 같은 모양의 짧은 쿼리들임. 패치 뒤 로그인당 쿼리 수가 늘었다면 그 패치가 출발점',
        no: '로그인당 쿼리 수는 적은데 쿼리 하나하나가 느리면 콜드 캐시(db-cold-cache)나 인덱스(db-no-index)',
        by: 'ops',
      },
      ref: [
        { t: 'Efficient Querying', u: 'https://learn.microsoft.com/en-us/ef/core/performance/efficient-querying', p: '.NET', n: 'ORM의 지연 로딩은 항목마다 쿼리를 한 번씩 더 보내는 N+1 문제를 만들어 성능을 크게 떨어뜨림, 한 번에 묶어 불러오기(eager loading) 권장' },
        { t: 'pg_stat_statements — track statistics of SQL planning and execution', u: 'https://www.postgresql.org/docs/current/pgstatstatements.html', p: 'PostgreSQL', n: '문장별 실행 횟수(calls)와 총 실행 시간을 모아 호출이 많은 쿼리 순위를 뽑음' },
        { t: 'Performance Schema Statement Digests and Sampling', u: 'https://dev.mysql.com/doc/refman/8.4/en/performance-schema-statement-digests.html', p: 'MySQL', n: 'events_statements_summary_by_digest로 같은 모양의 쿼리를 묶어 횟수·시간 집계' },
        { t: 'Statement Summary Tables', u: 'https://dev.mysql.com/doc/refman/8.4/en/performance-schema-statement-summary-tables.html', p: 'MySQL', n: '요약 테이블의 COUNT_STAR(실행 횟수)·SUM_TIMER_WAIT(총 시간)' },
        { t: 'Server Status Variables', u: 'https://dev.mysql.com/doc/refman/8.4/en/server-status-variables.html', p: 'MySQL', n: 'Questions: 클라이언트가 보낸 문장 수' },
      ] },
    { id: 'db-batch', t: '대량 배치 작업', en: 'Batch jobs during service',
      s: '랭킹 집계, 우편 일괄 발송, 오래된 데이터 정리를 운영 중에 돌리면 잠금과 디스크를 차지합니다.',
      c: ['운영 시간에 대량 작업 실행', '넓은 범위 잠금, 디스크·CPU 점유', '특정 시간대 거래·저장 실패, 로딩 지연'],
      sym: ['delay', 'dropped'], fx: ['lat', 'stall'], who: ['feature', 'server'], when: ['periodic'],
      own: ['srv', 'dba'],
      act: { game: '잘게 나눠 조금씩, 집계는 복제본에서.', infra: '집계용 복제본 제공, 배치는 한가한 시간대로 예약, 잠금 에스컬레이션·갭 락 대기 감시.' },
      more: 'SQL Server는 한 문장이 행 잠금을 약 5,000개 넘게 잡으면 테이블 잠금으로 바꿉니다(잠금 에스컬레이션). 그 순간 같은 테이블을 쓰는 모든 요청이 멈춥니다. MySQL도 기본 설정에서 범위 조건으로 고치면 행 사이 빈틈까지 잠가(갭 락) 새 행 추가를 막습니다.',
      sig: { k: 'periodic', g: 'DB 쿼리 지연, 잠금 대기' },
      chk: {
        look: '렉 시각에 돌던 긴 쿼리를 찾음. MySQL은 slow query log, PostgreSQL은 pg_stat_activity의 query_start·query를 보고, 같은 시각의 잠금 대기 지표와 배치 일정(크론, DB 이벤트 스케줄러)을 대조함. SQL Server는 lock_escalation 확장 이벤트로 잠금 에스컬레이션을 기록함',
        yes: '매번 같은 시각 대량 UPDATE·DELETE·집계 쿼리가 돌고, 그동안 잠금 대기와 디스크 이용률이 함께 오름',
        no: '그 시각에 긴 쿼리가 없으면 체크포인트(db-checkpoint)나 서버 백업(dk-backup)',
        by: 'ops',
      },
      ref: [
        { t: 'Transaction Locking and Row Versioning Guide', u: 'https://learn.microsoft.com/en-us/sql/relational-databases/sql-server-transaction-locking-and-row-versioning-guide', p: 'Microsoft SQL Server', n: '한 문장이 한 테이블(또는 인덱스)에서 잠금을 5,000개 이상 잡으면 잠금 에스컬레이션, lock_escalation 확장 이벤트로 기록' },
        { t: 'InnoDB Locking', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-locking.html', p: 'MySQL', n: 'InnoDB 기본 격리 수준 REPEATABLE READ에서는 검색·스캔에 next-key 잠금을 써서, 갭 락이 그 빈틈의 새 행 추가를 막음' },
        { t: 'The Slow Query Log', u: 'https://dev.mysql.com/doc/refman/8.4/en/slow-query-log.html', p: 'MySQL', n: 'long_query_time을 넘긴 쿼리를 실행 시간(Query_time)·잠금 시간(Lock_time)·읽은 행 수와 함께 기록' },
        { t: 'The Cumulative Statistics System (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/monitoring-stats.html', p: 'PostgreSQL', n: 'pg_stat_activity: 세션마다 지금 실행 중인 쿼리(query)와 시작 시각(query_start)' },
      ] },
    { id: 'db-failover', t: 'DB 장애 전환', en: 'Database failover',
      s: '주 DB가 죽어 예비 DB로 전환되는 동안 쓰기가 안 되고, 복제되지 못한 마지막 데이터는 사라질 수 있습니다.',
      c: ['주 DB 장애로 예비 DB가 승격', '전환 중 수 초~몇 분 쓰기 불가, 비동기 복제라면 미복제 데이터 유실 가능', '잠깐 모든 저장 실패, 아이템·경험치 롤백'],
      sym: ['dropped', 'freeze', 'disconnect', 'noconnect'], fx: ['stall', 'loss'], who: ['server'], when: ['random'],
      num: '관리형 DB의 자동 전환은 보통 수십 초~2분. 비동기 복제라면 복제 지연만큼(1초 미만~수 초) 최근 저장을 잃을 수 있습니다.',
      own: ['dba', 'srv'],
      act: { game: '재시도 가능한 저장, 끊긴 연결을 빨리 버리고 새 주소로 다시 맺는 설정(커넥션 풀·DNS 캐시), 전환 훈련 때 재연결 확인.', infra: '동기·반동기 복제(쓰기 지연과 맞바꿈), 전환 훈련, 전환 시간·복제 지연 모니터링.' },
      sig: { k: 'drop', g: 'DB 연결 수, 쓰기 오류 수' },
      chk: {
        look: 'DB 쪽 장애 전환 기록(RDS는 이벤트 RDS-EVENT-0013 전환 시작·RDS-EVENT-0049 전환 완료, 직접 운영하는 DB는 승격 로그)과 게임 서버의 DB 연결 수·연결 오류 수를 한 그래프에 놓음. 비동기 복제라면 장애 직전의 복제 지연(RDS ReplicaLag, PostgreSQL pg_stat_replication의 replay_lag)도 봄',
        yes: '저장 실패가 한 구간에 몰리고, 그 구간이 장애 전환 시작·완료 사이와 겹침. 되돌아간 양이 장애 직전 복제 지연과 비슷함. 전환이 끝난 뒤에도 오류가 이어지는 게임 서버는 옛 주소로 맺은 연결을 계속 쓰고 있는 것',
        no: '전환 기록이 없는 시각의 연결 끊김은 네트워크나 DB 과부하 쪽',
        by: 'ops',
      },
      ref: [
        { t: 'Failing over a Multi-AZ DB instance for Amazon RDS', u: 'https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.MultiAZ.Failover.html', p: 'AWS', n: 'Multi-AZ 전환은 보통 60~120초, 전환 뒤 연결을 다시 맺어야 하고 JVM의 DNS 캐시 TTL은 60초 이하 권장' },
        { t: 'High availability for Amazon Aurora', u: 'https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Concepts.AuroraHighAvailability.html', p: 'AWS', n: '장애 중 읽기·쓰기가 실패하고, 보통 60초 안(흔히 30초 안)에 복구' },
        { t: 'Semisynchronous Replication', u: 'https://dev.mysql.com/doc/refman/8.4/en/replication-semisync.html', p: 'MySQL', n: '비동기 복제는 주 DB가 죽으면 커밋한 트랜잭션이 복제본에 없을 수 있음, 반동기는 복제본 하나의 수신 확인을 기다려 줄이는 대신 지연이 늘어남' },
        { t: 'Log-Shipping Standby Servers (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/warm-standby.html', p: 'PostgreSQL', n: '로그 전달은 비동기라 주 서버가 죽으면 아직 보내지 못한 트랜잭션을 잃음, 스트리밍 복제 지연은 보통 1초 미만' },
        { t: 'Amazon RDS event categories and event messages', u: 'https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_Events.Messages.html', p: 'AWS', n: 'RDS-EVENT-0013: Multi-AZ 장애 전환 시작, RDS-EVENT-0049: Multi-AZ 장애 전환 완료' },
        { t: 'Amazon CloudWatch metrics for Amazon RDS', u: 'https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-metrics.html', p: 'AWS', n: 'ReplicaLag: 읽기 복제본이 원본보다 뒤처진 시간(초)' },
        { t: 'The Cumulative Statistics System (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/monitoring-stats.html', p: 'PostgreSQL', n: 'pg_stat_replication의 replay_lag: 주 서버가 WAL을 기록한 뒤 복제본이 적용했다고 알릴 때까지 걸린 시간' },
      ] },
    { id: 'db-save-interval', t: '긴 저장 주기로 인한 진행 유실', en: 'Periodic save window',
      s: '부하를 줄이려 몇 분에 한 번만 저장하면, 그 사이 서버가 죽을 때 진행이 사라집니다.',
      c: ['캐릭터 상태를 몇 분마다 한 번 저장', '그 사이 서버 크래시·장애 발생', '다시 접속하니 몇 분 전 상태(롤백)'],
      sym: ['dropped'], fx: ['loss'], who: ['server', 'zone'], when: ['random'],
      own: ['srv', 'dba'],
      act: { game: '중요 이벤트(거래, 희귀 획득)는 즉시 저장, 변경 로그 기록.', infra: '저장 주기를 줄였을 때 늘어나는 쓰기를 감당할 DB의 IOPS·CPU 여유 확인.' },
      sig: { k: 'drop', g: '접속 수, 롤백 신고 수' },
      chk: {
        look: '크래시·장애 시각과, 롤백을 신고한 캐릭터의 마지막 저장 시각(게임 서버의 저장 로그나 DB의 수정 시각 컬럼)을 나란히 놓음',
        yes: '되돌아간 시점이 크래시 직전의 마지막 저장 시각과 일치하고, 잃은 시간이 저장 주기보다 짧음',
        no: '게임 서버 로그에는 저장이 끝났다고 남아 있는데도 되돌아갔으면 DB 장애 전환의 데이터 유실(db-failover)이나 복제본에서 읽은 옛 값(db-replica-lag)',
        by: 'code',
      },
      ref: [
        { t: 'Asynchronous Commit (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/wal-async-commit.html', p: 'PostgreSQL', n: '기록을 모아 늦게 내리면 처리량이 오르는 대신, 장애 때 가장 최근 트랜잭션이 사라질 수 있음(같은 맞바꿈)' },
        { t: 'Redis persistence', u: 'https://redis.io/docs/latest/operate/oss_and_stack/management/persistence/', p: 'Redis', n: 'RDB 스냅샷을 몇 분마다 만들면 비정상 종료 때 마지막 몇 분의 데이터를 잃을 각오를 해야 함' },
      ] },
    { id: 'db-cache-stampede', t: '캐시 스탬피드', en: 'Cache stampede / thundering herd',
      s: '인기 데이터의 캐시가 동시에 만료되면 수천 개 요청이 한꺼번에 DB로 몰립니다.',
      c: ['Redis 등에 저장된 인기 데이터가 동시에 만료', '같은 데이터를 다시 만들려는 요청이 DB로 한꺼번에 몰림', 'DB 과부하로 여러 기능이 줄줄이 느려지거나 멈춤'],
      sym: ['delay', 'freeze', 'noconnect'], fx: ['stall', 'lat'], who: ['server'], when: ['periodic', 'event'],
      own: ['srv', 'dba'],
      act: { game: '만료 시각을 무작위로 분산, 한 요청만 갱신하고 나머지는 옛 값 사용.', infra: 'Redis 재시작·장애 때 캐시가 통째로 비지 않게 복제본·자동 전환 구성, 캐시가 비어도 버틸 DB 여유 확인.' },
      more: 'Redis가 재시작되거나 장애로 캐시가 통째로 비어도 같은 일이 생깁니다. 캐시를 믿고 DB를 작게 잡아 둔 구조일수록 위험합니다.',
      sim: 'arch',
      sig: { k: 'periodic', g: '캐시 적중률, DB 초당 쿼리 수' },
      chk: {
        look: 'Redis INFO의 keyspace_hits·keyspace_misses(적중률), expired_keys, 재시작 여부(uptime_in_seconds)를 DB 초당 쿼리 수와 겹쳐 보고, 그 순간 DB에서 같은 쿼리가 동시에 몇 개 도는지(MySQL SHOW PROCESSLIST, PostgreSQL pg_stat_activity) 셈',
        yes: '캐시 미스가 한순간 치솟는 시각에 DB 쿼리 수가 함께 솟고, 동시에 도는 쿼리 대부분이 같은 데이터를 읽는 같은 쿼리임. 인기 키의 만료 주기나 Redis 재시작 시각과 겹침',
        no: '캐시 미스는 평소와 같은데 DB 쿼리만 늘면 로그인 폭주(db-login-storm)나 배치(db-batch)',
        by: 'ops',
      },
      ref: [
        { t: 'Scaling Memcache at Facebook (NSDI \'13)', u: 'https://www.usenix.org/conference/nsdi13/technical-sessions/presentation/nishtala', p: 'USENIX', n: '자주 쓰는 키가 무효화되면 많은 읽기가 DB로 몰리는 thundering herd, 리스(한 클라이언트만 갱신)·옛 값 반환으로 막음, 캐시가 빈 클러스터는 따로 예열' },
        { t: 'Optimal Probabilistic Cache Stampede Prevention', u: 'https://www.vldb.org/pvldb/vol8/p886-vattani.pdf', p: 'VLDB Endowment', n: '인기 항목이 만료되면 여러 요청이 동시에 재생성하는 캐시 스탬피드, 만료 전에 확률적으로 미리 갱신해 막음' },
        { t: 'High availability with Redis Sentinel', u: 'https://redis.io/docs/latest/operate/oss_and_stack/management/sentinel/', p: 'Redis', n: '주 서버가 죽으면 복제본을 승격하는 자동 전환' },
        { t: 'INFO', u: 'https://redis.io/docs/latest/commands/info/', p: 'Redis', n: 'keyspace_hits·keyspace_misses(키 조회 성공·실패 수), expired_keys(만료된 키 수), uptime_in_seconds(시작 뒤 지난 시간)' },
        { t: 'SHOW PROCESSLIST Statement', u: 'https://dev.mysql.com/doc/refman/8.4/en/show-processlist.html', p: 'MySQL', n: '세션마다 실행 중인 문장(Info)과 현재 상태에 머문 시간(Time, 초)' },
        { t: 'The Cumulative Statistics System (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/monitoring-stats.html', p: 'PostgreSQL', n: 'pg_stat_activity: 세션마다 지금 실행 중인 쿼리(query)' },
      ] },
    { id: 'db-long-tx', t: '오래 열린 트랜잭션', en: 'Long-running transaction / MVCC purge lag',
      s: '트랜잭션 하나가 오래 열려 있으면 잠금을 계속 잡고 있고, DB가 옛 버전 데이터를 정리(purge)하지 못해 전체가 점점 느려집니다.',
      c: ['트랜잭션을 연 채 다른 서버 응답을 기다리거나, 운영 중 주 DB에서 긴 집계 쿼리 실행', '잡은 잠금이 풀리지 않고, 정리해야 할 옛 버전 데이터가 계속 쌓임', '그 행을 쓰는 기능 타임아웃, 몇 시간에 걸쳐 저장·조회가 전반적으로 느려짐'],
      sym: ['delay', 'dropped'], fx: ['lat', 'stall'], who: ['feature', 'server'], when: ['uptime', 'random'],
      own: ['srv', 'dba'],
      act: { game: '트랜잭션 안에서 네트워크 호출·사용자 입력 기다리지 않기, 집계 쿼리는 복제본에서.', infra: '오래 열린 트랜잭션 경보와 강제 종료, 집계용 복제본 제공, 언두 로그·죽은 행 증가 감시.' },
      more: 'DB는 읽는 쪽이 고치기 전 모습을 볼 수 있도록 옛 버전을 남겨 둡니다(MVCC). 가장 오래된 트랜잭션이 끝나야 이 기록을 지울 수 있어서, 트랜잭션 하나가 몇 시간 열려 있으면 MySQL은 언두 로그가, PostgreSQL은 VACUUM이 정리하지 못한 죽은 행(dead tuple)이 쌓입니다. SQL Server는 트랜잭션 로그가 줄지 않아 디스크를 채우기도 합니다.',
      sig: { k: 'ramp', g: '언두 로그 길이(History list length), 죽은 행 수' },
      chk: {
        look: 'MySQL은 INFORMATION_SCHEMA.INNODB_TRX의 trx_started로 가장 오래된 트랜잭션을 찾고, SHOW ENGINE INNODB STATUS의 TRANSACTIONS 섹션에 나오는 History list length(아직 정리하지 못한 언두 로그 양)를 봄. PostgreSQL은 pg_stat_activity의 xact_start와 state가 idle in transaction인 세션, pg_stat_user_tables의 n_dead_tup을 봄',
        yes: '몇 분~몇 시간 된 트랜잭션이 있고, 그동안 History list length나 n_dead_tup이 계속 오르다 그 트랜잭션을 끝낸 뒤 정리(purge·VACUUM)가 돌면서 줄어듦',
        no: '오래된 트랜잭션이 없는데 전반적으로 느리면 체크포인트(db-checkpoint)나 디스크 쪽',
        by: 'ops',
      },
      ref: [
        { t: 'InnoDB Multi-Versioning', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-multi-versioning.html', p: 'MySQL', n: '옛 버전을 볼 수 있는 트랜잭션이 남아 있으면 update 언두 로그를 버리지 못해 롤백 세그먼트가 커짐, 읽기만 하는 트랜잭션도 자주 커밋 권고' },
        { t: 'Routine Vacuuming (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/routine-vacuuming.html', p: 'PostgreSQL', n: '옛 행 버전은 다른 트랜잭션이 볼 수 있는 동안 지울 수 없고, 오래 열린 트랜잭션은 끝내거나 세션을 종료해야 함' },
        { t: 'Client Connection Defaults (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/runtime-config-client.html', p: 'PostgreSQL', n: 'idle_in_transaction_session_timeout: 트랜잭션을 연 채 쉬는 세션을 끊어 잠금을 오래 잡고 있지 못하게 함' },
        { t: 'Troubleshoot a full transaction log (SQL Server Error 9002)', u: 'https://learn.microsoft.com/en-us/sql/relational-databases/logs/troubleshoot-a-full-transaction-log-sql-server-error-9002', p: 'Microsoft SQL Server', n: '오래 실행 중인 활성 트랜잭션이 트랜잭션 로그 정리를 막음' },
        { t: 'The INFORMATION_SCHEMA INNODB_TRX Table', u: 'https://dev.mysql.com/doc/refman/8.4/en/information-schema-innodb-trx-table.html', p: 'MySQL', n: 'TRX_STARTED: 트랜잭션 시작 시각' },
        { t: 'Purge Configuration', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-purge-configuration.html', p: 'MySQL', n: '커밋된 트랜잭션의 언두 로그 목록(history list)을 purge가 정리, 밀린 양은 SHOW ENGINE INNODB STATUS의 TRANSACTIONS 섹션 History list length로 표시' },
        { t: 'The Cumulative Statistics System (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/monitoring-stats.html', p: 'PostgreSQL', n: 'pg_stat_activity의 xact_start(트랜잭션 시작 시각)와 state(idle in transaction), pg_stat_user_tables의 n_dead_tup(죽은 행 추정치)' },
      ] },
    { id: 'db-redis-block', t: 'Redis 느린 명령', en: 'Redis blocking commands (single-threaded)',
      s: 'Redis는 명령을 한 번에 하나씩 처리해서, 느린 명령 하나가 그 뒤의 모든 요청을 막습니다.',
      c: ['운영 중 KEYS로 전체 검색, 원소 수백만 개짜리 랭킹·목록을 통째로 읽거나 지움', '그 명령이 끝날 때까지 다른 모든 요청이 대기(수십 ms~수 초)', '세션·랭킹·캐시를 쓰는 기능이 동시에 멈칫, 로그인 지연'],
      sym: ['freeze', 'delay', 'noconnect'], fx: ['stall', 'lat'], who: ['server', 'feature'], when: ['random', 'periodic'],
      num: '보통 명령은 1ms 미만. 원소 수백만 개를 한 번에 다루면 수백 ms에서 수 초까지 걸리기도 합니다.',
      own: ['srv', 'dba'],
      act: { game: 'KEYS 대신 SCAN, 큰 키 쪼개기, 지우기는 UNLINK(백그라운드 삭제), 같은 초에 몰리는 만료 시각 분산.', infra: '느린 명령 기록(SLOWLOG) 감시, KEYS 같은 위험 명령은 운영 서버에서 막기, 큰 키 정기 점검, THP 끄고 fork할 메모리 여유 확보, RDB·AOF 저장은 복제본에서.' },
      more: '저장 파일(RDB 스냅샷)을 만들거나 AOF를 다시 쓰려고 프로세스를 복제(fork)하는 순간에도 멈춥니다. 요즘 서버에서 메모리 1GB당 약 10ms라, 30GB면 300ms쯤입니다. 큰 페이지(THP)를 켜 두면 fork 뒤 쓰기마다 큰 페이지를 통째로 복사해(copy-on-write) 멈춤과 메모리 사용이 크게 늘어서, 보통 THP를 끄고 메모리 여유를 넉넉히 둡니다. 같은 초에 만료되는 키가 아주 많을 때도 Redis가 지우느라 잠깐 멈춥니다.',
      sim: 'arch',
      sig: { k: 'random', g: 'Redis 응답 지연, 느린 명령 수' },
      chk: {
        look: 'SLOWLOG GET으로 slowlog-log-slower-than을 넘긴 명령을 보고, CONFIG SET latency-monitor-threshold로 지연 모니터(기본 꺼짐)를 켠 뒤 LATENCY LATEST·LATENCY DOCTOR로 fork·expire-cycle 같은 이벤트별 지연을 봄. INFO의 latest_fork_usec와 redis-cli --bigkeys로 fork 시간과 큰 키도 확인함',
        yes: '멈춘 시각에 SLOWLOG에 KEYS나 큰 키를 통째로 다루는 명령이 남아 있거나, LATENCY에 같은 시각 fork·expire-cycle 이벤트가 수십 ms 이상으로 기록됨',
        no: 'SLOWLOG·LATENCY가 비어 있는데 게임 서버 쪽에서만 느리면 네트워크나 게임 서버 안의 대기(SLOWLOG는 명령 실행 시간만 재고 클라이언트와 주고받는 시간은 넣지 않음)',
        by: 'ops',
      },
      ref: [
        { t: 'Diagnosing latency issues', u: 'https://redis.io/docs/latest/operate/oss_and_stack/management/optimization/latency/', p: 'Redis', n: '요청을 한 스레드가 차례로 처리해 느린 명령이 뒤를 모두 막음, KEYS 대신 SCAN, fork는 물리 서버·최신 VM 실측 1GB당 약 9~13ms, THP는 fork 뒤 복사로 지연·메모리 급증, 같은 초에 대량 만료되면 멈춤' },
        { t: 'KEYS', u: 'https://redis.io/docs/latest/commands/keys/', p: 'Redis', n: '운영 환경에서는 극히 조심해서 쓸 것, 큰 DB에서 성능을 망가뜨릴 수 있음(보급형 노트북에서 키 100만 개에 40ms)' },
        { t: 'UNLINK', u: 'https://redis.io/docs/latest/commands/unlink/', p: 'Redis', n: '키를 즉시 떼어 내고 메모리 회수는 다른 스레드에서 하는 비동기 삭제' },
        { t: 'SLOWLOG', u: 'https://redis.io/docs/latest/commands/slowlog/', p: 'Redis', n: 'slowlog-log-slower-than을 넘긴 명령을 기록하는 느린 명령 로그, 실행 시간에는 클라이언트와 주고받는 I/O가 빠짐' },
        { t: 'Redis latency monitoring', u: 'https://redis.io/docs/latest/operate/oss_and_stack/management/optimization/latency-monitor/', p: 'Redis', n: 'latency-monitor-threshold 기본 0(꺼짐), LATENCY LATEST·LATENCY DOCTOR, fork·expire-cycle 같은 이벤트별 지연 기록' },
        { t: 'INFO', u: 'https://redis.io/docs/latest/commands/info/', p: 'Redis', n: 'latest_fork_usec: 마지막 fork에 걸린 시간(마이크로초)' },
        { t: 'Redis CLI', u: 'https://redis.io/docs/latest/develop/tools/cli/', p: 'Redis', n: '--bigkeys: 키 공간을 훑어 큰 키를 찾음' },
      ] },
    { id: 'db-plan-flip', t: '실행 계획 변경으로 인한 쿼리 지연', en: 'Query plan regression (stats, parameter sniffing)',
      s: '코드는 그대로인데 DB가 같은 쿼리를 처리하는 방법(실행 계획)을 바꾸면, 어제 2ms였던 쿼리가 오늘 수백 ms가 됩니다.',
      c: ['통계 자동 갱신, DB 재시작, 데이터 분포 변화로 DB가 실행 계획을 새로 세움', '인덱스를 안 타는 계획이 골라져 같은 쿼리가 수십~수백 배 느려지고 커넥션이 묶임', '배포도 없었는데 특정 기능 로딩이 갑자기 느려지고 다른 요청까지 대기'],
      sym: ['delay', 'noconnect'], fx: ['lat', 'stall'], who: ['feature', 'server'], when: ['random'],
      own: ['dba', 'srv'],
      act: { game: '값에 따라 결과 수가 크게 다른 쿼리는 나눠 쓰거나 계획 힌트 검토, 인덱스를 확실히 타는 쿼리 설계.', infra: '느린 쿼리와 실행 계획 기록 감시, 좋은 계획 고정(SQL Server 쿼리 저장소 등), 통계 갱신 시각 관리.' },
      more: 'SQL Server는 처음 들어온 값에 맞춰 세운 계획을 다시 씁니다(파라미터 스니핑). 아이템이 몇 개뿐인 새 캐릭터로 세운 계획이 아이템 수만 개인 오래된 캐릭터에게 쓰이면 크게 느려지고, 반대 경우도 흔합니다. 재시작으로 계획이 지워지면 멀쩡해졌다가 다시 나빠지기도 합니다.',
      sim: 'dbpool',
      sig: { k: 'step', g: '쿼리별 평균 실행 시간' },
      chk: {
        look: '같은 모양 쿼리의 평균 시간을 주기적으로 모아 추이를 봄. MySQL은 events_statements_summary_by_digest의 AVG_TIMER_WAIT, PostgreSQL은 pg_stat_statements의 mean_exec_time(12 이하는 mean_time)임. 느려진 전후의 실행 계획은 EXPLAIN이나 PostgreSQL auto_explain, SQL Server는 쿼리 저장소의 회귀된 쿼리(Regressed Queries) 화면으로 비교함',
        yes: '배포가 없던 시각에 한 쿼리의 평균 시간이 계단처럼 몇십 배 오르고, 그 시점이 통계 갱신·DB 재시작과 겹치며 실행 계획이 바뀌어 있음',
        no: '실행 계획은 그대로인데 느려졌으면 데이터 증가, 잠금 대기(db-hot-row), 디스크 쪽',
        by: 'ops',
      },
      ref: [
        { t: 'Query Processing Architecture Guide', u: 'https://learn.microsoft.com/en-us/sql/relational-databases/query-processing-architecture-guide', p: 'Microsoft SQL Server', n: '파라미터 스니핑: 컴파일·재컴파일 때 들어온 파라미터 값에 맞춰 실행 계획을 세움' },
        { t: 'Parameter Sensitive Plan Optimization', u: 'https://learn.microsoft.com/en-us/sql/relational-databases/performance/parameter-sensitive-plan-optimization', p: 'Microsoft SQL Server', n: '데이터 분포가 고르지 않으면 캐시된 계획 하나가 모든 파라미터 값에 맞지 않음' },
        { t: 'Monitor performance by using the Query Store', u: 'https://learn.microsoft.com/en-us/sql/relational-databases/performance/monitoring-performance-by-using-the-query-store', p: 'Microsoft SQL Server', n: '통계·스키마·인덱스 변화로 계획이 바뀌고 계획 캐시는 최신 계획만 둠, 쿼리 저장소의 계획 강제로 좋은 계획 고정, 회귀된 쿼리(Regressed Queries) 화면으로 느려진 쿼리와 계획 비교' },
        { t: 'Statement Summary Tables', u: 'https://dev.mysql.com/doc/refman/8.4/en/performance-schema-statement-summary-tables.html', p: 'MySQL', n: 'events_statements_summary_by_digest: 같은 모양 쿼리별 COUNT_STAR·AVG_TIMER_WAIT(평균 시간)' },
        { t: 'pg_stat_statements — track statistics of SQL planning and execution', u: 'https://www.postgresql.org/docs/current/pgstatstatements.html', p: 'PostgreSQL', n: '문장별 calls, total_exec_time, mean_exec_time(평균 실행 시간)' },
        { t: 'pg_stat_statements (PostgreSQL 12 Documentation)', u: 'https://www.postgresql.org/docs/12/pgstatstatements.html', p: 'PostgreSQL', n: '12까지는 열 이름이 total_time·mean_time' },
        { t: 'auto_explain — log execution plans of slow queries', u: 'https://www.postgresql.org/docs/current/auto-explain.html', p: 'PostgreSQL', n: 'auto_explain.log_min_duration보다 오래 걸린 쿼리의 실행 계획을 로그에 남김' },
      ] },
    { id: 'db-ddl-lock', t: '운영 중 스키마 변경(DDL) 잠금', en: 'Schema change lock (DDL / metadata lock)',
      s: '서비스 중에 테이블에 컬럼이나 인덱스를 추가하면, 잠깐 필요한 잠금 하나 때문에 그 테이블을 쓰는 모든 요청이 대기할 수 있습니다.',
      c: ['핫픽스로 운영 중인 테이블에 컬럼·인덱스 추가', '스키마 변경이 앞서 열린 긴 트랜잭션을 기다리고, 뒤에 오는 모든 요청은 그 스키마 변경을 기다림', '그 테이블을 쓰는 기능(인벤토리, 우편 등)이 통째로 멈추고 타임아웃'],
      sym: ['delay', 'dropped', 'noconnect'], fx: ['stall'], who: ['feature', 'server'], when: ['random', 'login'],
      own: ['dba', 'srv'],
      act: { game: '스키마 변경이 든 핫픽스는 DB 인프라와 일정 협의, 새 컬럼이 없어도 동작하는 코드를 먼저 배포.', infra: '잠금 대기 한도를 짧게 걸고 실패하면 다시 시도, 긴 트랜잭션이 없을 때 실행, 온라인 변경 도구 사용, 큰 테이블은 점검 시간에.' },
      more: 'MySQL은 스키마를 바꿀 때 메타데이터 잠금을, PostgreSQL은 가장 강한 테이블 잠금을 잠깐 잡습니다. 변경 자체는 순식간이어도, 앞에 끝나지 않은 트랜잭션이 하나 있으면 그 뒤로 모든 요청이 대기합니다.',
      sig: { k: 'step', g: '잠금 대기 세션 수, 그 테이블의 쿼리 지연' },
      chk: {
        look: 'MySQL은 SHOW PROCESSLIST에서 State가 Waiting for table metadata lock인 세션을 세고, sys.schema_table_lock_waits로 막고 있는 세션(blocking_pid)을 찾음. PostgreSQL은 pg_locks에서 granted가 false인 요청과 AccessExclusiveLock을 보고, pg_blocking_pids()로 막고 있는 세션을 찾음',
        yes: '스키마 변경을 시작한 시각부터 그 테이블을 쓰는 모든 쿼리가 잠금 대기로 쌓이고, 맨 앞에 끝나지 않은 트랜잭션이나 스키마 변경 문장이 있음',
        no: '대기가 특정 행에만 몰리고 같은 테이블의 다른 행은 잘 처리되면 핫 로우(db-hot-row)',
        by: 'ops',
      },
      ref: [
        { t: 'Online DDL Performance and Concurrency', u: 'https://dev.mysql.com/doc/refman/8.4/en/innodb-online-ddl-performance.html', p: 'MySQL', n: '온라인 DDL도 끝낼 때 배타적 메타데이터 잠금이 잠깐 필요, 긴 트랜잭션이 있으면 기다리고, 기다리는 잠금 요청이 뒤의 모든 트랜잭션을 막음' },
        { t: 'Server System Variables', u: 'https://dev.mysql.com/doc/refman/8.4/en/server-system-variables.html', p: 'MySQL', n: 'lock_wait_timeout: 메타데이터 잠금 대기 한도, 기본값 31,536,000초(1년)' },
        { t: 'ALTER TABLE (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/sql-altertable.html', p: 'PostgreSQL', n: '따로 적지 않은 ALTER TABLE은 가장 강한 ACCESS EXCLUSIVE 잠금을 잡음' },
        { t: 'Client Connection Defaults (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/runtime-config-client.html', p: 'PostgreSQL', n: 'lock_timeout: 잠금을 이 시간 넘게 기다리면 문장을 중단' },
        { t: 'General Thread States', u: 'https://dev.mysql.com/doc/refman/8.4/en/general-thread-states.html', p: 'MySQL', n: 'Waiting for table metadata lock: 메타데이터 잠금을 기다리는 스레드 상태' },
        { t: 'The schema_table_lock_waits and x$schema_table_lock_waits Views', u: 'https://dev.mysql.com/doc/refman/8.4/en/sys-schema-table-lock-waits.html', p: 'MySQL', n: '메타데이터 잠금을 기다리는 세션(waiting_query)과 막고 있는 세션(blocking_pid)' },
        { t: 'pg_locks (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/view-pg-locks.html', p: 'PostgreSQL', n: 'granted가 false면 잠금을 기다리는 중, mode에 AccessExclusiveLock 같은 잠금 종류' },
        { t: 'System Information Functions and Operators (PostgreSQL Documentation)', u: 'https://www.postgresql.org/docs/current/functions-info.html', p: 'PostgreSQL', n: 'pg_blocking_pids(): 지정한 세션이 잠금을 못 얻게 막고 있는 세션 목록' },
      ] },
  ]);

